import numpy as np
from PIL import Image

def variants(path):
    im = Image.open(path).convert('RGB')
    out=[]
    for scale in (1,2,4):
        a = im if scale==1 else im.resize((im.width//scale, im.height//scale), Image.LANCZOS)
        f = np.asarray(a,dtype=np.float32)/127.5-1
        R,G=f[...,0],f[...,1]
        for op in ('central','forward'):
            if op=='central':
                x=(R[2:,1:-1]-R[:-2,1:-1])/2; y=(G[1:-1,2:]-G[1:-1,:-2])/2
            else:
                x=np.diff(R,axis=0)[:,:-1]; y=np.diff(G,axis=1)[:-1,:]
            for q in (25,50,75):
                m=(x**2+y**2)>np.percentile(x**2+y**2,q)
                s=(x[m]*y[m]).mean()/np.sqrt((x[m]**2).mean()*(y[m]**2).mean())
                out.append(s)
    return np.array(out)

