def _sq_name(sq):
    return chr(ord('a') + sq % 8) + chr(ord('1') + sq // 8)


def _inside(f, r):
    return 0 <= f < 8 and 0 <= r < 8


def _square_attacked(board, sq, by_white):
    """True if square `sq` is attacked by the side `by_white`."""
    f, r = sq % 8, sq // 8

    # pawns: a white attacker sits one rank "below" sq, black one rank above
    pawn = 'P' if by_white else 'p'
    pr = r - 1 if by_white else r + 1
    if 0 <= pr < 8:
        for df in (-1, 1):
            pf = f + df
            if 0 <= pf < 8 and board[pr * 8 + pf] == pawn:
                return True

    knight = 'N' if by_white else 'n'
    for df, dr in _KNIGHT_DELTAS:
